const LEGAL={
 privacy:{it:{title:'Privacy',intro:'Informazioni sul funzionamento attuale della pagina COLAVA.',sections:[['Gestore','COLAVA è un progetto di Altered Venganza, Trieste, Italia. P. IVA 01433140322.'],['Dati nella pagina','La pagina non contiene moduli di iscrizione, analytics o pixel pubblicitari. La consultazione delle anteprime non richiede un indirizzo email. I servizi di hosting possono trattare dati tecnici di connessione, come indirizzo IP e richieste HTTP, per erogare e proteggere il sito.'],['Preferenze sul dispositivo','La scelta relativa alle preferenze è salvata nel browser per 180 giorni. La lingua viene ricordata solo se attivi la relativa opzione. Puoi cambiare scelta dal footer e cancellare i dati dalle impostazioni del browser.'],['Servizi esterni','I collegamenti a fornitori e a Stripe aprono servizi esterni, con informative proprie. Questa pagina non riceve né memorizza numeri di carta.'],['Informativa in completamento','Prima dell’apertura delle vendite vanno completati recapito privacy, indirizzo del gestore e dettagli sul trattamento dei dati degli ordini e sulla loro conservazione. Le informazioni qui presenti descrivono la pagina attuale e non costituiscono ancora l’informativa completa della futura attività di vendita.']]},en:{title:'Privacy',intro:'Information about how the current COLAVA page operates.',sections:[['Operator','COLAVA is a project by Altered Venganza, Trieste, Italy. VAT number 01433140322.'],['Data on this page','The page contains no signup forms, analytics or advertising pixels. Reading previews does not require an email address. Hosting services may process technical connection data, such as IP addresses and HTTP requests, to deliver and secure the site.'],['Device preferences','Your preferences choice is stored in your browser for 180 days. Language is remembered only if you enable that option. Change your choice through the footer or remove stored data in your browser settings.'],['External services','Supplier and Stripe links open external services with their own privacy notices. This page does not receive or store card numbers.'],['Notice being completed','Before sales open, the privacy contact, operator address and details of order-data processing and retention need to be completed. This information describes the current page and is not yet the full notice for future sales operations.']]}},
 cookies:{it:{title:'Cookie e preferenze',intro:'Controlli semplici, riferiti alle funzioni realmente presenti.',sections:[['Nessun tracciamento integrato','Il codice della pagina COLAVA non imposta cookie di analytics o pubblicitari e non incorpora video o social di terze parti. Il banner permette di scegliere se ricordare la lingua; non attiva strumenti pubblicitari.'],['Cosa viene memorizzato','colava-privacy-v1: scelta delle preferenze e scadenza, in localStorage per 180 giorni. colava-language: lingua IT o EN, solo se richiesta, valida finché la scelta resta valida. I dati rimangono nel browser e il codice COLAVA non li invia a un server.'],['Come cambiare scelta','Apri “Gestisci preferenze” nel footer. “Solo essenziali” disattiva il salvataggio della lingua e rimuove la lingua precedentemente salvata. Lo switch IT/EN continua a funzionare durante la navigazione.'],['Hosting e collegamenti','Il servizio di hosting o il suo accesso riservato possono utilizzare meccanismi tecnici propri. Le preferenze COLAVA non controllano questi servizi né i cookie dei siti esterni aperti tramite link.'],['Riferimento','<a href="https://www.garanteprivacy.it/home/docweb/-/docweb-display/docweb/9677876" target="_blank" rel="noopener">Linee guida del Garante su cookie e altri strumenti di tracciamento</a>. Aggiornamento: 20 settembre 2026.']]},en:{title:'Cookies & preferences',intro:'Simple controls for the functions actually present.',sections:[['No integrated tracking','COLAVA page code sets no analytics or advertising cookies and embeds no third-party video or social widgets. The banner lets you choose whether to remember language; it does not enable advertising tools.'],['What is stored','colava-privacy-v1: preferences choice and expiry, in localStorage for 180 days. colava-language: IT or EN language, only when requested and while the preferences choice remains valid. Data stays in the browser and COLAVA code does not send it to a server.'],['Changing your choice','Open “Manage preferences” in the footer. “Essential only” disables language persistence and removes the saved language. The IT/EN switch continues to work while browsing.'],['Hosting and links','The hosting service or its restricted access may use its own technical mechanisms. COLAVA preferences do not control those services or cookies on external websites opened through links.'],['Reference','<a href="https://www.garanteprivacy.it/home/docweb/-/docweb-display/docweb/9677876" target="_blank" rel="noopener">Italian Data Protection Authority guidance on cookies and tracking</a>. Updated: 20 September 2026.']]}},
 digital:{it:{title:'Guida digitale e acquisti',intro:'Food Forms 01 · 19 € · edizioni italiano + inglese.',sections:[['Cosa comprende','Due PDF separati di 24 pagine ciascuno: italiano e inglese. Tre esercizi, schemi didattici, calcolo delle quantità, diagnosi dei difetti e schede stampabili. Stampi, ingredienti e prodotti fisici non sono inclusi.'],['Prima di acquistare','Puoi consultare gratuitamente l’anteprima di 6 pagine nella lingua scelta. È un estratto del volume e non richiede pagamento o registrazione.'],['Pagamento e consegna','Il collegamento Stripe è in configurazione; gli acquisti non sono ancora attivi. Prima dell’apertura saranno indicati modalità e tempi di consegna dei PDF, contatto assistenza e condizioni di vendita. Il solo pagamento Stripe non implica una consegna automatica già configurata.'],['Uso della guida','Uso personale dell’acquirente; non rivendere o redistribuire i PDF. La guida riguarda stampi alimentari pronti, non la fabbricazione del silicone. I concept fotografici AI non sono fotografie di prove eseguite da COLAVA.'],['Prodotti futuri','Custom Food, Custom Candles, materiali, stampi e kit sono in preparazione. Non sono inclusi nel prezzo della guida e non sono attualmente ordinabili.']]},en:{title:'Digital guide & purchases',intro:'Food Forms 01 · €19 · English + Italian editions.',sections:[['What is included','Two separate 24-page PDFs: English and Italian. Three exercises, teaching diagrams, quantity calculations, troubleshooting and printable worksheets. Molds, ingredients and physical products are not included.'],['Before buying','Read the free 6-page preview in your chosen language. It is an extract of the guide and requires no payment or registration.'],['Payment and delivery','The Stripe link is being configured; purchases are not active yet. PDF delivery method and timing, support contact and sales terms will be provided before sales open. Stripe payment alone does not mean automatic delivery is already configured.'],['Using the guide','For the purchaser’s personal use; do not resell or redistribute the PDFs. The guide uses ready-made food molds and does not teach silicone manufacture. AI photographic concepts are not photos of COLAVA-tested projects.'],['Future products','Custom Food, Custom Candles, materials, molds and kits are in preparation. They are not included in the guide price and cannot currently be ordered.']]}}
};
function legalMarkup(page,lang){const d=LEGAL[page][lang];return `<h1>${d.title}</h1><p>${d.intro}</p>${d.sections.map(v=>`<section><h2>${v[0]}</h2><p>${v[1]}</p></section>`).join('')}`;}
if(typeof module!=='undefined')module.exports={LEGAL,legalMarkup};
if(typeof document!=='undefined'){const l=new URLSearchParams(location.search).get('lang')==='it'?'it':'en',page=document.body.dataset.legal;document.documentElement.lang=l;document.title=LEGAL[page][l].title+' · COLAVA';document.getElementById('legal-main').innerHTML=legalMarkup(page,l);document.getElementById('legal-footer').innerHTML=COLAVAPrivacy.footer(l,'food');document.getElementById('legal-home').href='index.html?lang='+l;document.getElementById('legal-language').href=page+'.html?lang='+(l==='it'?'en':'it');document.getElementById('legal-language').textContent=l==='it'?'EN':'IT';}
